import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-integration-service-boundary/SlackDigestBoundaryBpmn/SlackDigestBoundaryBpmn.bpmn')
root = tree.getroot()
ns = {
  'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
  'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
  'uipath': 'http://uipath.org/schema/bpmn'
}

# Collect all declared ids
ids = set(e.get('id') for e in root.iter() if e.get('id'))
print('IDs declared:', sorted(ids))

# Check refs resolve
flows = root.findall('.//bpmn:sequenceFlow', ns)
for f in flows:
    src = f.get('sourceRef'); tgt = f.get('targetRef')
    if src not in ids: print('MISSING sourceRef:', src)
    if tgt not in ids: print('MISSING targetRef:', tgt)

# Check all incoming/outgoing ref flow ids
for e in root.iter():
    tag = e.tag.split('}')[-1] if '}' in e.tag else e.tag
    if tag in ('incoming', 'outgoing'):
        val = (e.text or '').strip()
        if val not in ids: print('MISSING incoming/outgoing ref:', val)

# Check BPMNShape/BPMNEdge coverage
shapes = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNShape', ns)}
edges  = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNEdge',  ns)}
nodes  = set(e.get('id') for e in root.findall('.//bpmn:process/*', ns) if e.get('id') and 'sequenceFlow' not in e.tag)
flow_ids = set(f.get('id') for f in flows)
for n in nodes:
    if n not in shapes: print('MISSING BPMNShape for:', n)
for f in flow_ids:
    if f not in edges: print('MISSING BPMNEdge for:', f)

print('XML WELL-FORMED: OK')
print('shapes cover:', sorted(shapes))
print('edges cover:', sorted(edges))
"

python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-integration-service-boundary/SlackDigestBoundaryBpmn/SlackDigestBoundaryBpmn.bpmn')
root = tree.getroot()
ns = {
  'bpmn':   'http://www.omg.org/spec/BPMN/20100524/MODEL',
  'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
  'uipath': 'http://uipath.org/schema/bpmn'
}
ids = set(e.get('id') for e in root.iter() if e.get('id'))
flows = root.findall('.//bpmn:sequenceFlow', ns)
errors = []
for f in flows:
    for attr in ('sourceRef','targetRef'):
        v = f.get(attr)
        if v not in ids: errors.append('MISSING '+attr+': '+v)
for e in root.iter():
    tag = e.tag.split('}')[-1] if '}' in e.tag else e.tag
    if tag in ('incoming','outgoing'):
        v = (e.text or '').strip()
        if v not in ids: errors.append('MISSING ref: '+v)
shapes = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNShape', ns)}
edges  = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNEdge',  ns)}
# nodes = direct children of process except sequenceFlow
proc = root.find('.//bpmn:process', ns)
for child in proc:
    cid = child.get('id')
    tag = child.tag.split('}')[-1]
    if cid and tag != 'sequenceFlow' and tag != 'extensionElements':
        if cid not in shapes: errors.append('MISSING BPMNShape: '+cid)
for f in flows:
    fid = f.get('id')
    if fid not in edges: errors.append('MISSING BPMNEdge: '+fid)
if errors:
    for e in errors: print('ERROR:', e)
else:
    print('VALID - all refs resolve, all nodes/flows have DI')
"
